var calc_output = [];

var rope = parseInt(rope, 10);
var pfo = parseInt(pfo, 10);

var classification = "";


// classification
if (rope === 1 && pfo === 1) {
    classification = "Probable";
} else if ((rope === 1 && pfo === 0) || (rope === 0 && pfo === 1)) {
    classification = "Possible";
} else if (rope === 0 && pfo === 0) {
    classification = "Unlikely";
} else {
    classification = "Unknown";
}

// mini output
calc_output.push({
    name: 'mini',
    value: classification,
    value_text: '',
    message: 'PFO-attributable stroke likelihood',
});

